using System;
using System.Linq;
using System.Collections.Generic;
using ColdWarStruggle.Core;
using ColdWarStruggle.Infrastructure;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace ColdWarStruggle.Tests
{
    public class ChinaCardPlayTests
    {
        internal static readonly CardId China=new CardId("card.china");
        internal static CountryId C(string id)=>OpsRegionalBudgetTests.C(id);
        internal static string Data()=>PlayInfluenceEventTests.Read("Data/Cards/deluxe-2015/persistent-effects-batch1.parameters.json");
        internal static string Schema()=>PlayInfluenceEventTests.Read("Docs/Contracts/persistent-effects-batch1.schema.json");
        internal static GameState Ready(int level=5,string card="card.olympic_games",int vp=0)
        {
            var s=PlayScoringTests.Ready(card,vp,configure:d=>{var f=d.Risk.Defcon;var risk=new PracticeRiskDefinition(d.Risk.Coup,new DefconDefinition(f.Map,level,f.MaximumLevel,f.NuclearLevel,f.TurnStartImprovement,f.BattlegroundCoupDegradation,f.RestrictedActions,f.BlockedRegions),d.Risk.Military,d.Risk.Victory);return new ActionPracticeDefinition(d.Cards,d.Ops,d.Space,d.Calendar,risk,d.Scoring,PlayInfluenceEventTests.Effects(f.Map,d.Cards),PlayDefconVpEventTests.Effects(d.Cards),PlayTurnOpsEventTests.Effects(d.Cards),RealignmentTests.Definition(),new ChinaCardDefinition(d.Cards,f.Map,China,new OpsRegionalBonus("china","region.asia",1)));});
            var board=s.Countries.ToDictionary(x=>x.Key,x=>x.Value);foreach(var c in new[]{"vietnam","thailand","japan"})board[C(c)]=new CountryState(0,1);board[C("angola")]=new CountryState(3,3);return PlayScoringTests.Replace(s,board,Pcg32Random.FromSeed(42,54).Capture());
        }
        internal static GameState SetChina(GameState s,PlayerSide side,CardFace face)
        {var c=s.Cards;var hands=new Dictionary<PlayerSide,IReadOnlyList<CardId>>{{PlayerSide.US,c.GetHand(PlayerSide.US)},{PlayerSide.USSR,c.GetHand(PlayerSide.USSR)}};return PlayInfluenceEventTests.Copy(s,cards:new CardZones(s.Practice.Definition.Cards,c.DrawPile,hands,c.EraReserve,c.DiscardPile,c.RemovedCards,c.ResolvingCards,new ChinaCardState(China,side,face),c.EnteredEras));}
        internal static CardActionTransition Use(GameState s,CardActionKind kind,CountryId? target=null)=>ActionPracticeRules.Plan(s,s.Practice.Actor,kind,"china-use",China,target);
        internal static GameState AdvanceOrdinary(GameState s)
        {s=PlayTurnOpsEventTests.Give(s,s.Practice.Actor,"card.olympic_games");var begin=ActionPracticeRules.Plan(s,s.Practice.Actor,CardActionKind.Influence,"ordinary",new CardId("card.olympic_games"));Assert.That(begin.Accepted,Is.True);var done=ActionPracticeRules.Plan(begin.NextState,s.Practice.Actor,CardActionKind.FinishInfluence,"end");Assert.That(done.Accepted,Is.True);return done.NextState;}
        static void SameOrdinaryZones(CardZones before,CardZones after)
        {Assert.That(after.GetHand(PlayerSide.US),Is.EqualTo(before.GetHand(PlayerSide.US)));Assert.That(after.GetHand(PlayerSide.USSR),Is.EqualTo(before.GetHand(PlayerSide.USSR)));Assert.That(after.DrawPile,Is.EqualTo(before.DrawPile));Assert.That(after.DiscardPile,Is.EqualTo(before.DiscardPile));Assert.That(after.RemovedCards,Is.EqualTo(before.RemovedCards));Assert.That(after.EraReserve,Is.EqualTo(before.EraReserve));Assert.That(after.ResolvingCards,Is.Empty);}
        [TestCase(CardActionKind.Influence)] [TestCase(CardActionKind.Realignment)]
        public void China_transfers_face_down_on_start_and_finishes_once_without_ordinary_disposition(CardActionKind kind)
        {var s=Ready();var p=Use(s,kind);Assert.That(p.Accepted,Is.True,p.Error.ToString());var n=p.NextState;Assert.That(n.Cards.China.Owner,Is.EqualTo(PlayerSide.US));Assert.That(n.Cards.China.Face,Is.EqualTo(CardFace.FaceDown));Assert.That(n.Practice.ActiveCard,Is.EqualTo(China));Assert.That(n.Practice.Actor,Is.EqualTo(PlayerSide.USSR));Assert.That(n.Operations.Budget,Is.EqualTo(5));SameOrdinaryZones(s.Cards,n.Cards);Pcg32RandomTests.Same(s.RandomState,n.RandomState);var done=ActionPracticeRules.Plan(n,PlayerSide.USSR,kind==CardActionKind.Influence?CardActionKind.FinishInfluence:CardActionKind.FinishRealignment,"end");Assert.That(done.Accepted,Is.True);Assert.That(done.NextState.Practice.CompletedActions,Is.EqualTo(1));SameOrdinaryZones(s.Cards,done.NextState.Cards);Assert.That(ActionPracticeRules.CanPlay(done.NextState,PlayerSide.US,China,CardActionKind.Influence),Is.EqualTo(RuleError.ChinaUnavailable));Assert.That(Use(s,kind).NextState.Cards.China.Owner,Is.EqualTo(PlayerSide.US));}
        [Test] public void Influence_uses_fifth_Asia_point_and_cannot_be_used_by_new_owner_mid_action()
        {var s=Ready();var p=Use(s,CardActionKind.Influence);Assert.That(p.Accepted,Is.True);var n=p.NextState;var placement=InfluenceRules.PlanPlacement(n,n.Operations,Enumerable.Repeat(C("vietnam"),5).ToArray());Assert.That(placement.Accepted,Is.True);Assert.That(placement.NextState.GetInfluence(C("vietnam"),PlayerSide.USSR),Is.EqualTo(6));Assert.That(ActionPracticeRules.Plan(n,PlayerSide.US,CardActionKind.Space,"steal",China).Error,Is.EqualTo(RuleError.WrongActor));}
        [TestCase("japan",5)] [TestCase("thailand",5)] [TestCase("angola",4)]
        public void Coup_region_quote_sets_both_strength_and_military_then_transfers(string target,int expected)
        {var s=Ready();var board=s.Countries.ToDictionary(x=>x.Key,x=>x.Value);board[C(target)]=new CountryState(20,0);s=PlayScoringTests.Replace(s,board);var p=Use(s,CardActionKind.Coup,C(target));Assert.That(p.Accepted,Is.True,p.Error.ToString());Assert.That(p.CoupReceipt.Request.Strength,Is.EqualTo(expected));Assert.That(p.NextState.Practice.Risk.Military.UssrEarned,Is.EqualTo(expected));Assert.That(p.NextState.Practice.CompletedActions,Is.EqualTo(1));Assert.That(p.NextState.Cards.China.Owner,Is.EqualTo(PlayerSide.US));SameOrdinaryZones(s.Cards,p.NextState.Cards);}
        [Test] public void Nuclear_coup_keeps_transferred_China_and_interrupted_root_without_resolving_duplicate()
        {var s=Ready(level:2);var p=Use(s,CardActionKind.Coup,C("angola"));Assert.That(p.Accepted,Is.True);Assert.That(p.NextState.Ended,Is.True);Assert.That(p.NextState.Practice.CompletedActions,Is.Zero);Assert.That(p.NextState.Practice.ActiveCard,Is.EqualTo(China));Assert.That(p.NextState.Cards.China.Owner,Is.EqualTo(PlayerSide.US));Assert.That(p.NextState.Cards.China.Face,Is.EqualTo(CardFace.FaceDown));SameOrdinaryZones(s.Cards,p.NextState.Cards);}
        [Test] public void Space_has_no_regional_bonus_and_China_never_enters_discard()
        {var s=Ready();Assert.That(ActionPracticeRules.QuoteCard(s,PlayerSide.USSR,China,OpsValuePurpose.Space).GeneralValue,Is.EqualTo(4));var p=Use(s,CardActionKind.Space);Assert.That(p.Accepted,Is.True,p.Error.ToString());Assert.That(p.SpaceReceipt,Is.Not.Null);Assert.That(p.NextState.Practice.Space.UssrAttempts,Is.EqualTo(1));Assert.That(p.NextState.Practice.CompletedActions,Is.EqualTo(1));Assert.That(p.NextState.Cards.China.Face,Is.EqualTo(CardFace.FaceDown));SameOrdinaryZones(s.Cards,p.NextState.Cards);}
        [Test] public void Realignment_keeps_every_paid_Asia_roll_and_rejects_outside_fifth_without_rng()
        {var s=Ready();var board=s.Countries.ToDictionary(x=>x.Key,x=>x.Value);foreach(var c in new[]{"japan","thailand","iran"})board[C(c)]=new CountryState(100,100);s=PlayScoringTests.Replace(s,board);var p=Use(s,CardActionKind.Realignment);Assert.That(p.Accepted,Is.True);s=p.NextState;for(int i=0;i<4;i++){p=ActionPracticeRules.Plan(s,PlayerSide.USSR,CardActionKind.RollRealignment,"roll",target:C("japan"));Assert.That(p.Accepted,Is.True);s=p.NextState;}Assert.That(s.SpentOps,Is.EqualTo(4));var before=s.RandomState;Assert.That(ActionPracticeRules.CheckRealignmentTarget(s,PlayerSide.USSR,C("iran")),Is.EqualTo(RuleError.InsufficientBudget));var denied=ActionPracticeRules.Plan(s,PlayerSide.USSR,CardActionKind.RollRealignment,"outside",target:C("iran"));Assert.That(denied.Error,Is.EqualTo(RuleError.InsufficientBudget));Assert.That(denied.NextState,Is.Null);Pcg32RandomTests.Same(s.RandomState,before);p=ActionPracticeRules.Plan(s,PlayerSide.USSR,CardActionKind.RollRealignment,"fifth",target:C("thailand"));Assert.That(p.Accepted,Is.True);Assert.That(p.NextState.SpentOps,Is.EqualTo(5));Assert.That(p.NextState.Operations.RegionalBudget.Spent,Is.EqualTo(5));Assert.That(p.NextState.Practice.Risk.Military.UssrEarned,Is.Zero);Assert.That(p.NextState.Practice.Risk.Defcon.Level,Is.EqualTo(5));}
        [TestCase("card.containment",5)] [TestCase("card.red_scare_purge",4)]
        public void Regional_quote_uses_actual_actor_flat_effects(string effect,int expected)
        {var s=Ready(card:effect);var activation=PlayTurnOpsEventTests.Play(s,effect);Assert.That(activation.Accepted,Is.True);s=SetChina(activation.NextState,PlayerSide.US,CardFace.FaceUp);var p=Use(s,CardActionKind.Influence);Assert.That(p.Accepted,Is.True);Assert.That(p.NextState.Operations.Budget,Is.EqualTo(expected));Assert.That(p.NextState.Operations.RegionalBudget.Quote.Actor,Is.EqualTo(PlayerSide.US));}
        [Test] public void Ownership_face_and_unsupported_event_routes_are_enforced()
        {var s=Ready();Assert.That(ActionPracticeRules.CanPlay(s,PlayerSide.US,China,CardActionKind.Influence),Is.EqualTo(RuleError.WrongActor));Assert.That(Use(SetChina(s,PlayerSide.US,CardFace.FaceUp),CardActionKind.Influence).Error,Is.EqualTo(RuleError.CardNotOwned));Assert.That(Use(SetChina(s,PlayerSide.USSR,CardFace.FaceDown),CardActionKind.Influence).Error,Is.EqualTo(RuleError.ChinaUnavailable));foreach(var kind in new[]{CardActionKind.Event,CardActionKind.Scoring,CardActionKind.OpponentOpsFirst})Assert.That(Use(s,kind).Error,Is.Not.EqualTo(RuleError.None));}
        [TestCase(8,1,true)] [TestCase(8,2,false)] [TestCase(10,0,true)] [TestCase(10,1,false)]
        [TestCase(9,1,true)] [TestCase(9,2,false)] [TestCase(11,0,true)] [TestCase(11,1,false)]
        public void Scoring_obligation_reserves_enough_remaining_actions_including_current(int completed,int held,bool allowed)
        {var s=Ready();for(int i=0;i<completed;i++)s=AdvanceOrdinary(s);var actor=s.Practice.Actor;var other=actor==PlayerSide.US?PlayerSide.USSR:PlayerSide.US;s=SetChina(s,actor,CardFace.FaceUp);var scoring=s.Practice.Definition.Cards.Cards.Where(c=>c.Kind==CardKind.Scoring).Select(c=>c.Id).ToArray();foreach(var id in scoring)s=PlayTurnOpsEventTests.Give(s,other,id.Value);foreach(var id in scoring.Take(held))s=PlayTurnOpsEventTests.Give(s,actor,id.Value);var error=ActionPracticeRules.CanPlay(s,actor,China,CardActionKind.Space);Assert.That(error,Is.EqualTo(allowed?RuleError.None:RuleError.ScoringMustBePlayed));}
        [TestCase(CardActionKind.Influence)] [TestCase(CardActionKind.Realignment)] [TestCase(CardActionKind.Coup)] [TestCase(CardActionKind.Space)]
        public void Overflow_does_not_transfer_card_or_publish_rng(CardActionKind kind)
        {var s=PlayScoringTests.Replace(Ready(),version:long.MaxValue);var p=Use(s,kind,kind==CardActionKind.Coup?C("angola"):(CountryId?)null);Assert.That(p.Error,Is.EqualTo(RuleError.NumericOverflow));Assert.That(p.NextState,Is.Null);Assert.That(s.Cards.China.Owner,Is.EqualTo(PlayerSide.USSR));Assert.That(s.Cards.China.Face,Is.EqualTo(CardFace.FaceUp));}
        [Test] public void Tied_realignment_still_spends_and_records_region_without_changing_influence()
        {var s=Ready();var board=s.Countries.ToDictionary(x=>x.Key,x=>x.Value);board[C("vietnam")]=new CountryState(100,100);s=PlayScoringTests.Replace(s,board);s=Use(s,CardActionKind.Realignment).NextState;var p=ActionPracticeRules.Plan(s,PlayerSide.USSR,CardActionKind.RollRealignment,"tie",target:C("vietnam"));Assert.That(p.Accepted,Is.True);Assert.That(p.Realignment.Removed,Is.Zero);Assert.That(p.NextState.Countries[C("vietnam")],Is.EqualTo(s.Countries[C("vietnam")]));Assert.That(p.NextState.SpentOps,Is.EqualTo(1));Assert.That(p.NextState.Operations.RegionalBudget.HasTargets,Is.True);Assert.That(p.NextState.RandomState.DrawCount,Is.EqualTo(s.RandomState.DrawCount+2));}
        [TestCase(CardActionKind.Influence)] [TestCase(CardActionKind.Realignment)]
        public void Finish_overflow_keeps_already_transferred_card_and_root_prefix(CardActionKind kind)
        {var s=Use(Ready(),kind).NextState;s=PlayScoringTests.Replace(s,sequence:long.MaxValue);var p=ActionPracticeRules.Plan(s,s.Practice.Actor,kind==CardActionKind.Influence?CardActionKind.FinishInfluence:CardActionKind.FinishRealignment,"end");Assert.That(p.Error,Is.EqualTo(RuleError.NumericOverflow));Assert.That(p.NextState,Is.Null);Assert.That(s.Cards.China.Owner,Is.EqualTo(PlayerSide.US));Assert.That(s.Cards.China.Face,Is.EqualTo(CardFace.FaceDown));Assert.That(s.Practice.CompletedActions,Is.Zero);}
        [Test] public void Space_victory_preserves_immediate_transfer_and_stops_root_completion()
        {var initial=Ready(vp:-19);bool success=false;for(ulong seed=0;seed<24 && !success;seed++){var s=PlayScoringTests.Replace(initial,random:Pcg32Random.FromSeed(seed,54).Capture());var r=Use(s,CardActionKind.Space);Assert.That(r.Accepted,Is.True);if(!r.SpaceReceipt.Success)continue;success=true;Assert.That(r.NextState.Ended,Is.True);Assert.That(r.NextState.Practice.CompletedActions,Is.Zero);Assert.That(r.NextState.Practice.Risk.Result.Winner,Is.EqualTo(PlayerSide.USSR));Assert.That(r.NextState.Cards.China.Owner,Is.EqualTo(PlayerSide.US));Assert.That(r.NextState.Cards.China.Face,Is.EqualTo(CardFace.FaceDown));Assert.That(r.NextState.Practice.ActiveCard,Is.EqualTo(China));SameOrdinaryZones(s.Cards,r.NextState.Cards);}Assert.That(success,Is.True);}
        [Test] public void Loader_reads_verified_shared_China_source_and_rejects_unverified_or_wrong_region()
        {var s=Ready();var d=ChinaCardDefinitionLoader.LoadSubset(Data(),Schema(),s.Practice.Definition.Cards,s.Map);Assert.That(d.Card,Is.EqualTo(China));Assert.That(d.Bonus.Region,Is.EqualTo("region.asia"));Assert.That(d.Bonus.Delta,Is.EqualTo(1));var json=JObject.Parse(Data());json["source_bonuses"]["china"]["source_refs"][0]["verification"]="Pending";Assert.That(()=>ChinaCardDefinitionLoader.LoadSubset(json.ToString(),Schema(),d.Cards,s.Map),Throws.InstanceOf<ArgumentException>());json=JObject.Parse(Data());json["source_bonuses"]["china"]["region_id"]="region.unknown";Assert.That(()=>ChinaCardDefinitionLoader.LoadSubset(json.ToString(),Schema(),d.Cards,s.Map),Throws.InstanceOf<ArgumentException>());}
    }
}
